function Avatar({ initials, tone = "teal", size = "md" }: { initials: string; tone?: string; size?: "sm" | "md" | "lg" }) {
  const tones: Record<string, string> = { teal: "bg-[#d8f0e9] text-[#167363]", blue: "bg-[#dbe8fa] text-[#35649d]", violet: "bg-[#e9e1f7] text-[#7657a7]", amber: "bg-[#faecd2] text-[#a16d25]", coral: "bg-[#f8dfd6] text-[#a45b45]", slate: "bg-[#e5e9ed] text-[#637180]", rose: "bg-[#f4dde9] text-[#a14b75]", mint: "bg-[#d8f0e9] text-[#167363]" };
  return <div className={cn("grid shrink-0 place-items-center rounded-full font-display font-bold", tones[tone] || tones.teal, size === "sm" ? "h-8 w-8 text-[10px]" : size === "lg" ? "h-14 w-14 text-base" : "h-10 w-10 text-xs")}>{initials}</div>;
}

function StatusPill({ status }: { status: string }) {
  const styles: Record<string, string> = { "Checked-in": "bg-[#e2f5ef] text-[#167363]", "In consultation": "bg-[#e4edfb] text-[#3c67a5]", Confirmed: "bg-[#fff1d8] text-[#9d6c22]", Completed: "bg-[#eef1f1] text-[#68777a]", Requested: "bg-[#edf0f3] text-[#65717a]", "No-show": "bg-[#fae4e0] text-[#ad5c4c]", "On duty": "bg-[#e2f5ef] text-[#167363]", Available: "bg-[#e5f0fb] text-[#35649d]", "In consult": "bg-[#fff1d8] text-[#9d6c22]", Verified: "bg-[#e4edfb] text-[#3c67a5]", Released: "bg-[#e2f5ef] text-[#167363]", Draft: "bg-[#edf0f3] text-[#65717a]", "In progress": "bg-[#fff1d8] text-[#9d6c22]", Issued: "bg-[#e4edfb] text-[#3c67a5]", Dispensed: "bg-[#e2f5ef] text-[#167363]", Critical: "bg-[#fae4e0] text-[#ad5c4c]", Active: "bg-[#e2f5ef] text-[#167363]", Pending: "bg-[#fff1d8] text-[#9d6c22]", Paid: "bg-[#e2f5ef] text-[#167363]", "Pending review": "bg-[#fff1d8] text-[#9d6c22]" };
  return <span className={cn("inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-semibold", styles[status] || "bg-slate-100 text-slate-600")}><span className="h-1.5 w-1.5 rounded-full bg-current opacity-80" />{status}</span>;
}

function MetricCard({ label, value, delta, icon: Icon, tint, trend = "up" }: { label: string; value: string; delta: string; icon: any; tint: string; trend?: "up" | "down" }) {
  return <div className="card-shadow rounded-[20px] border border-white/80 bg-white p-5 transition duration-200 hover:-translate-y-0.5 hover:shadow-xl"><div className="flex items-start justify-between"><div className={cn("grid h-10 w-10 place-items-center rounded-2xl", tint)}><Icon size={18} strokeWidth={1.8} /></div><button className="text-slate-300 transition hover:text-slate-600"><MoreHorizontal size={18} /></button></div><p className="mt-5 text-[12px] font-medium text-slate-500">{label}</p><div className="mt-1 flex items-end gap-3"><p className="font-display text-[26px] font-extrabold tracking-tight text-[#16343b]">{value}</p><span className={cn("mb-1 inline-flex items-center gap-0.5 text-[10px] font-bold", trend === "up" ? "text-[#20866f]" : "text-[#bb675a]")}>{trend === "up" ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{delta}</span></div></div>;
}

function PageHeader({ eyebrow, title, subtitle, action, onAction }: { eyebrow: string; title: string; subtitle: string; action?: string; onAction: ToastFn }) {
  return <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.14em] text-[#559385]">{eyebrow}</p><h1 className="font-display text-[29px] font-extrabold tracking-[-.035em] text-[#173842]">{title}</h1><p className="mt-1 text-[13px] text-slate-500">{subtitle}</p></div>{action && <button onClick={() => onAction(action)} className="inline-flex w-fit items-center gap-2 rounded-xl bg-[#173f47] px-4 py-2.5 text-[12px] font-bold text-white shadow-lg shadow-[#173f47]/15 transition hover:-translate-y-0.5 hover:bg-[#12545a] active:scale-[.97]"><Plus size={15} />{action}</button>}</div>;
}

function SectionCard({ title, eyebrow, action, children, className }: { title: string; eyebrow?: string; action?: string; children: any; className?: string }) {
  return <section className={cn("card-shadow rounded-[22px] bg-white p-5 sm:p-6", className)}><div className="flex items-start justify-between gap-4"><div>{eyebrow && <p className="text-[10px] font-bold uppercase tracking-[.14em] text-slate-400">{eyebrow}</p>}<h2 className="mt-1 font-display text-[17px] font-extrabold text-[#173842]">{title}</h2></div>{action && <button className="text-[11px] font-bold text-[#398174] hover:underline">{action}</button>}</div>{children}</section>;
}

