function InsurancePage({ onAction }: { onAction: ToastFn }) { return <div className="fade-up space-y-5"><PageHeader eyebrow="Coverage & claims" title="Insurance workspace" subtitle="Configurable coverage, authorization and claim status without assuming a single insurer workflow." action="Add policy" onAction={onAction} /><div className="grid gap-4 sm:grid-cols-3"><MetricCard label="Active policies" value="12" delta="3 providers" icon={ShieldCheck} tint="bg-[#e0f4ed] text-[#278870]" /><MetricCard label="Claims this month" value="28" delta="8.6%" icon={FileCheck2} tint="bg-[#e3edfa] text-[#5279b0]" /><MetricCard label="Awaiting authorization" value="04" delta="Review now" icon={Clock3} tint="bg-[#fdf0d8] text-[#aa772b]" /></div><div className="grid gap-5 xl:grid-cols-[1fr_.85fr]"><SectionCard eyebrow="Policy records" title="Active coverage"><div className="mt-4 space-y-3">{[["NepalCare Cooperative", "POL-NC-88901", "Anisha Koirala", "80% outpatient", "Active"], ["Himalayan Employee Health", "POL-HE-20481", "Bikash Adhikari", "Inpatient + diagnostics", "Active"], ["Bagmati Family Plan", "POL-BF-11820", "Saraswati Thapa", "Consultation only", "Pending"]].map(([provider, policy, member, coverage, status]) => <div key={policy} className="rounded-2xl border border-[#edf2ef] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-[12px] font-bold text-[#2b4b51]">{provider}</p><p className="mt-1 font-mono text-[9px] text-slate-400">{policy} · Member {member}</p></div><StatusPill status={status} /></div><div className="mt-3 flex flex-wrap gap-4 text-[10px] text-slate-500"><span>Coverage · <b className="text-[#2b4b51]">{coverage}</b></span><span>Valid through · <b className="text-[#2b4b51]">31 Dec 2026</b></span></div></div>)}</div></SectionCard><SectionCard eyebrow="Claim detail" title="CLM-2026-0092"><div className="mt-4 space-y-3"><Detail label="Provider" value="NepalCare Cooperative" /><Detail label="Authorization" value="Approved · AUTH-8821" /><Detail label="Claim amount" value="रु 12,400" /><Detail label="Claim status" value="Submitted · awaiting insurer" /><div className="rounded-2xl bg-[#f7faf8] p-4"><p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Claim workflow</p><div className="mt-4 flex items-center gap-2">{["Draft", "Authorized", "Submitted", "Adjudicated"].map((step, i) => <div key={step} className="flex flex-1 flex-col items-center gap-2"><div className={cn("h-2 w-2 rounded-full", i < 3 ? "bg-[#3b9b84]" : "bg-slate-300")} /><span className="text-center text-[9px] text-slate-400">{step}</span></div>)}</div></div></div><button onClick={() => onAction("Insurance document uploaded")} className="mt-4 inline-flex items-center gap-2 rounded-xl border border-[#e0ebe6] px-3 py-2 text-[10px] font-bold text-slate-600"><CloudUpload size={13} />Add claim document</button></SectionCard></div></div>; }

function InteroperabilityPage({ onAction }: { onAction: ToastFn }) { const resources = ["Patient", "Practitioner", "Organization", "Encounter", "Observation", "Condition", "AllergyIntolerance", "MedicationRequest", "MedicationDispense", "DiagnosticReport", "ServiceRequest", "ImagingStudy", "DocumentReference", "CarePlan", "Appointment", "Consent"]; return <div className="fade-up space-y-5"><PageHeader eyebrow="Future-ready architecture" title="Interoperability" subtitle="A visual readiness layer for FHIR-compatible resources, API boundaries and DICOM/PACS integration." action="Review API map" onAction={onAction} /><div className="grid gap-4 sm:grid-cols-3"><MetricCard label="FHIR resources" value="16" delta="Mapped concepts" icon={Network} tint="bg-[#e0f4ed] text-[#278870]" /><MetricCard label="API domains" value="15" delta="Versioned /api/v1" icon={Globe2} tint="bg-[#e3edfa] text-[#5279b0]" /><MetricCard label="DICOM readiness" value="72%" delta="Metadata UI" icon={Database} tint="bg-[#fdf0d8] text-[#aa772b]" /></div><div className="grid gap-5 xl:grid-cols-[1fr_.9fr]"><SectionCard eyebrow="FHIR-compatible concepts" title="Resource map"><div className="mt-4 flex flex-wrap gap-2">{resources.map((resource) => <button key={resource} onClick={() => onAction(`Open FHIR mapping · ${resource}`)} className="rounded-xl border border-[#dfeae5] bg-[#f8fbf9] px-3 py-2 font-mono text-[10px] font-bold text-[#3c8174] transition hover:border-[#99caba] hover:bg-[#eef8f4]">{resource}</button>)}</div><div className="mt-5 rounded-2xl border border-[#e3eee9] bg-[#f7fcfa] p-4"><p className="text-[10px] font-bold uppercase tracking-widest text-[#5b8d80]">Example future mapping</p><p className="mt-2 font-mono text-[10px] text-[#47766d]">GET /fhir/Patient/NP-PT-000184</p><p className="mt-1 text-[10px] leading-4 text-slate-400">Frontend-only representation. No real API endpoint is implemented.</p></div></SectionCard><SectionCard eyebrow="DICOM / PACS architecture" title="Imaging integration boundary"><div className="mt-4 space-y-3">{[["DICOM metadata", "Study / series / instance fields"], ["PACS / VNA connector", "Future external imaging store"], ["Patient matching", "Internal Patient ID + accession"], ["Report release", "Authorized doctor / patient access"]].map(([title, detail]) => <div key={title} className="flex items-center gap-3 rounded-2xl border border-[#edf2ef] p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#e9f0fb] text-[#5279b0]"><Database size={15} /></div><div className="flex-1"><p className="text-[11px] font-bold text-[#2b4b51]">{title}</p><p className="mt-1 text-[10px] text-slate-400">{detail}</p></div><StatusPill status="Ready" /></div>)}</div></SectionCard></div><SectionCard eyebrow="API boundaries" title="Future endpoint groups"><div className="mt-4 grid gap-2 sm:grid-cols-3">{["/api/v1/auth", "/api/v1/patients", "/api/v1/organizations", "/api/v1/appointments", "/api/v1/encounters", "/api/v1/diagnoses", "/api/v1/prescriptions", "/api/v1/pharmacies", "/api/v1/laboratory", "/api/v1/radiology", "/api/v1/documents", "/api/v1/consents", "/api/v1/audit", "/api/v1/notifications", "/fhir/Patient"].map((endpoint) => <button key={endpoint} onClick={() => onAction(`Open architecture · ${endpoint}`)} className="rounded-xl bg-[#f7faf8] px-3 py-2.5 text-left font-mono text-[10px] text-[#487d71] hover:bg-[#eef7f3]">{endpoint}</button>)}</div></SectionCard></div>; }

function NotificationsPage({ onAction }: { onAction: ToastFn }) { const [read, setRead] = useState<string[]>([]); const notifications = [["New appointment request", "A patient has requested a new appointment.", "12 min ago", "Appointment"], ["Laboratory result ready", "A new healthcare notification is ready for secure review.", "34 min ago", "Laboratory"], ["Medication refill reminder", "One medication may need a refill soon.", "1 hr ago", "Medication"], ["Security alert", "A new device session was recorded for your account.", "2 hrs ago", "Security"], ["Document uploaded", "A new document is available in your secure workspace.", "Yesterday", "Documents"]]; return <div className="fade-up space-y-5"><PageHeader eyebrow="Stay informed" title="Notifications" subtitle="Helpful, privacy-conscious updates without exposing unnecessary medical information." action="Mark all as read" onAction={() => { setRead(notifications.map((n) => n[0])); onAction("All notifications marked read"); }} /><div className="grid gap-5 xl:grid-cols-[1fr_.7fr]"><SectionCard eyebrow="Inbox" title="Your notifications"><div className="mt-4 space-y-2">{notifications.map(([title, detail, time, type]) => { const isRead = read.includes(title); return <div key={title} className={cn("flex gap-3 rounded-2xl border p-4 transition", isRead ? "border-[#edf2ef] bg-white opacity-65" : "border-[#cfe5dc] bg-[#f7fcfa]")}><div className={cn("grid h-9 w-9 shrink-0 place-items-center rounded-xl", type === "Security" ? "bg-[#fae4e0] text-[#ad5c4c]" : "bg-[#e5f3ed] text-[#328171]")}>{type === "Security" ? <ShieldAlert size={15} /> : type === "Laboratory" ? <FlaskConical size={15} /> : <Bell size={15} />}</div><div className="min-w-0 flex-1"><p className="text-[11px] font-bold text-[#2b4b51]">{title}</p><p className="mt-1 text-[10px] leading-4 text-slate-400">{detail}</p><p className="mt-2 text-[9px] text-slate-400">{time} · {type}</p></div>{!isRead && <button onClick={() => setRead([...read, title])} className="self-start rounded-lg p-1.5 text-[#3d8a7a] hover:bg-[#e4f3ed]"><Check size={14} /></button>}</div>; })}</div></SectionCard><SectionCard eyebrow="Delivery preferences" title="How we notify"><div className="mt-4 space-y-3"><ToggleRow title="In-app notifications" detail="Always on for secure workspace activity." checked onChange={() => onAction("In-app notifications are required")} /><ToggleRow title="Email notifications" detail="Architecture ready · provider not connected." checked={false} onChange={() => onAction("Email provider configuration")} /><ToggleRow title="SMS reminders" detail="Architecture ready · provider not connected." checked={false} onChange={() => onAction("SMS provider configuration")} /></div></SectionCard></div></div>; }

function SettingsPage({ onAction }: { onAction: ToastFn }) { const [language, setLanguage] = useState("English"); return <div className="fade-up space-y-5"><PageHeader eyebrow="System controls" title="Settings" subtitle="Configure profile, organization, roles, notifications, language, accessibility and privacy." action="Save changes" onAction={() => onAction("Settings saved locally")} /><div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><SectionCard eyebrow="Settings navigation" title="Workspace controls"><div className="mt-4 space-y-1">{["Profile", "Organization", "Users", "Roles & permissions", "Notifications", "Security", "Language", "Accessibility", "Privacy", "Data retention", "Backup & recovery"].map((item, i) => <button key={item} onClick={() => onAction(`${item} settings`)} className={cn("flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[11px] font-bold", i === 0 ? "bg-[#e8f6f0] text-[#277767]" : "text-slate-500 hover:bg-[#f7faf8]")}><Settings size={14} />{item}<ChevronRight size={13} className="ml-auto text-slate-300" /></button>)}</div></SectionCard><div className="space-y-5"><SectionCard eyebrow="Profile" title="Suman Shahi · Super Admin"><div className="mt-4 grid gap-4 sm:grid-cols-2"><FormField label="Full name" value="Suman Shahi" placeholder="Full name" /><FormField label="Work email" value="suman.shahi@demo.swasthyaflow.np" placeholder="Work email" /><FormField label="Organization" value="Himalaya Care Hospital" placeholder="Organization" /><FormField label="Role" value="Super Admin" placeholder="Role" /></div></SectionCard><SectionCard eyebrow="Language & accessibility" title="Personalize your workspace"><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-[10px] font-bold uppercase tracking-widest text-slate-400">Interface language</span><select value={language} onChange={(e) => setLanguage(e.target.value)} className="h-10 w-full rounded-xl border border-[#e2ebe6] bg-[#fbfdfc] px-3 text-[12px] outline-none"><option>English</option><option>नेपाली</option></select><span className="mt-2 block text-[10px] text-slate-400">More languages can be added through the i18n layer.</span></label><div><p className="mb-1.5 text-[10px] font-bold uppercase tracking-widest text-slate-400">Accessibility</p><div className="space-y-2"><ToggleRow title="Reduced motion" detail="Respect system preference" checked={false} onChange={() => onAction("Reduced motion preference")} /><ToggleRow title="High contrast labels" detail="Use text with status colors" checked onChange={() => onAction("High contrast labels enabled")} /></div></div></div></SectionCard><SectionCard eyebrow="Data retention & recovery" title="Future infrastructure controls"><div className="grid gap-3 sm:grid-cols-2"><Detail label="Retention policy" value="Configurable by organization / record type" /><Detail label="Last backup" value="17 Sep 2026 · Encrypted demo" /><Detail label="Recovery point objective" value="RPO · Configurable" /><Detail label="Recovery time objective" value="RTO · Configurable" /><Detail label="Restore testing" value="Last test · 30 Aug 2026" /><Detail label="Disaster recovery plan" value="Documented · Review quarterly" /></div></SectionCard></div></div></div>; }

function ModulePage({ page, onAction }: { page: string; onAction: ToastFn }) { const config: Record<string, { icon: any; title: string; eyebrow: string; subtitle: string; primary: string; stat: string; columns: string[] }> = { "Prescriptions": { icon: Pill, title: "Prescription centre", eyebrow: "Medication management", subtitle: "Create, sign and track demo prescriptions across connected care teams.", primary: "Create prescription", stat: "18 active", columns: ["Prescription", "Patient", "Prescriber", "Issued", "Status"] }, "Consultations": { icon: MessageSquareText, title: "Consultation workspace", eyebrow: "Clinical documentation", subtitle: "Capture structured clinical notes while keeping the patient story in view.", primary: "New consultation", stat: "04 drafts", columns: ["Patient", "Chief complaint", "Clinician", "Updated", "Status"] } }; const item = config[page] || config.Prescriptions; return <div className="fade-up space-y-5"><PageHeader eyebrow={item.eyebrow} title={item.title} subtitle={item.subtitle} action={item.primary} onAction={onAction} /><SectionCard eyebrow="Connected workflow" title="Recent demo records"><div className="mt-4 space-y-3">{[["Anisha Koirala", "NP-PT-000184", "Ready for professional review", "In progress"], ["Bikash Adhikari", "NP-PT-000176", "Recent care event", "Verified"], ["Saraswati Thapa", "NP-PT-000169", "Follow-up record", "Completed"]].map(([name, id, detail, status]) => <div key={id} className="flex flex-wrap items-center gap-3 rounded-2xl border border-[#edf2ef] p-4"><Avatar initials={name.split(" ").map((p) => p[0]).join("")} tone="teal" size="sm" /><div className="min-w-[180px] flex-1"><p className="text-[11px] font-bold text-[#2b4b51]">{name} <span className="ml-2 font-mono text-[9px] font-normal text-slate-400">{id}</span></p><p className="mt-1 text-[10px] text-slate-400">{detail}</p></div><StatusPill status={status} /><button onClick={() => onAction(`Open ${name}`)} className="rounded-lg p-2 text-slate-300 hover:bg-slate-50 hover:text-slate-600"><ChevronRight size={15} /></button></div>)}</div></SectionCard><div className="grid gap-4 sm:grid-cols-3"><MetricCard label="Active records" value={item.stat} delta="Local mock state" icon={item.icon} tint="bg-[#e0f4ed] text-[#278870]" /><MetricCard label="Needs review" value="03" delta="2 priority" icon={AlertCircle} tint="bg-[#fdf0d8] text-[#aa772b]" /><MetricCard label="Permission status" value="Allowed" delta="Role scoped" icon={ShieldCheck} tint="bg-[#e3edfa] text-[#5279b0]" /></div></div>; }

function BreakGlassModal({ onClose, onAction }: { onClose: () => void; onAction: ToastFn }) { const [reason, setReason] = useState(""); const [confirmed, setConfirmed] = useState(false); return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-[#0b2930]/50 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-[26px] bg-white p-6 shadow-2xl"><div className="flex items-start gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-[#fae4e0] text-[#ad5c4c]"><ShieldAlert size={21} /></div><div className="flex-1"><p className="font-display text-[17px] font-extrabold text-[#5e3b35]">BREAK-GLASS ACCESS</p><p className="mt-1 text-[11px] text-[#9c6f65]">Emergency access is monitored and audited.</p></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-50"><X size={17} /></button></div><div className="mt-5 rounded-2xl border border-[#f1d5ce] bg-[#fff9f7] p-4"><p className="text-[11px] leading-5 text-[#754d45]">Use this workflow only when immediate care requires access outside normal authorization. The reason, user identity and timestamp will be recorded in the audit trail.</p></div><label className="mt-5 block"><span className="mb-1.5 block text-[10px] font-bold uppercase tracking-widest text-slate-400">Reason for emergency access</span><textarea value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Describe the emergency context" className="min-h-24 w-full rounded-xl border border-[#e2ebe6] bg-[#fbfdfc] px-3 py-2.5 text-[12px] outline-none focus:border-[#d88a78]" /></label><label className="mt-4 flex items-start gap-3"><input type="checkbox" checked={confirmed} onChange={(e) => setConfirmed(e.target.checked)} className="mt-0.5 h-4 w-4 accent-[#b36251]" /><span className="text-[11px] leading-5 text-slate-600">I confirm this is an emergency, I am Suman Shahi, and I understand this action will create an audit event.</span></label><div className="mt-6 flex justify-end gap-2"><button onClick={onClose} className="rounded-xl border border-[#e0ebe6] px-4 py-2.5 text-[11px] font-bold text-slate-600">Cancel</button><button disabled={!reason.trim() || !confirmed} onClick={() => { onAction("Break-glass event recorded"); onClose(); }} className="rounded-xl bg-[#ad5c4c] px-4 py-2.5 text-[11px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Confirm emergency access</button></div></div></div>; }

function AuthModal({ onClose, onAction }: { onClose: () => void; onAction: ToastFn }) {
  const [mode, setMode] = useState("Login");
  const [mfa, setMfa] = useState(false);
  const [verified, setVerified] = useState(false);
  const modes = ["Login", "Forgot password", "Reset password", "Email verification", "MFA / 2FA", "Sessions"];
  const submit = () => {
    if (mode === "Login") setMfa(true);
    else if (mode === "Email verification") setVerified(true);
    else onAction(`${mode} demo submitted`);
  };
  return <div className="fixed inset-0 z-[75] flex items-center justify-center bg-[#0b2930]/55 p-4 backdrop-blur-sm">
    <div className="grid w-full max-w-4xl overflow-hidden rounded-[28px] bg-white shadow-2xl lg:grid-cols-[.82fr_1.18fr]">
      <div className="hidden bg-[#173f47] p-8 text-white lg:block">
        <div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-[13px] bg-[#e3f4ed] text-[#1c7766]"><HeartPulse size={21} /></div><div><p className="font-display text-[16px] font-extrabold">SwasthyaFlow</p><p className="text-[9px] font-bold uppercase tracking-[.2em] text-[#91b8ac]">Nepal healthcare OS</p></div></div>
        <div className="mt-20"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-[#a7d7c9]">Secure workspace</p><h2 className="mt-3 font-display text-[31px] font-extrabold leading-tight tracking-[-.04em]">Care connected.<br />Trust visible.</h2><p className="mt-4 max-w-xs text-[12px] leading-5 text-white/60">A frontend representation of the future authentication, session and access-control experience.</p></div>
        <div className="mt-16 space-y-3">{["Strong password policy", "MFA / 2FA ready", "Tenant-aware sessions", "Audited access events"].map((item) => <div key={item} className="flex items-center gap-2 text-[11px] text-white/75"><CheckCircle2 size={14} className="text-[#8dd0bd]" />{item}</div>)}</div>
      </div>
      <div className="p-5 sm:p-8">
        <div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#559385]">Demo authentication</p><h2 className="mt-2 font-display text-[24px] font-extrabold tracking-tight text-[#173842]">{mode === "Login" ? "Welcome back" : mode}</h2><p className="mt-1 text-[12px] text-slate-400">Frontend-only flow · No real credentials are processed.</p></div><button onClick={onClose} className="rounded-xl p-2 text-slate-400 hover:bg-slate-50"><X size={18} /></button></div>
        <div className="mt-5 flex gap-1 overflow-x-auto border-b border-[#edf2ef] pb-1">{modes.map((item) => <button key={item} onClick={() => { setMode(item); setMfa(false); setVerified(false); }} className={cn("whitespace-nowrap rounded-lg px-2.5 py-2 text-[10px] font-bold", mode === item ? "bg-[#e7f5ef] text-[#287767]" : "text-slate-400 hover:bg-[#f7faf8]")}>{item}</button>)}</div>
        {mode === "Sessions" ? <div className="mt-5 space-y-3">{[["Current browser", "Chrome on macOS · Kathmandu", "Active now"], ["Mobile device", "Safari on iPhone · Lalitpur", "18 min ago"], ["Workstation", "Edge on Windows · Kathmandu", "2 hrs ago"]].map(([title, detail, time], i) => <div key={title} className="flex items-center gap-3 rounded-2xl border border-[#edf2ef] p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#e9f6f1] text-[#278870]"><KeyRound size={15} /></div><div className="min-w-0 flex-1"><p className="text-[11px] font-bold text-[#2b4b51]">{title}</p><p className="mt-1 text-[10px] text-slate-400">{detail}</p></div><span className="text-[10px] text-slate-400">{time}</span>{i > 0 && <button onClick={() => onAction(`Session revoked · ${title}`)} className="rounded-lg p-2 text-slate-300 hover:text-[#b36251]"><LogOut size={14} /></button>}</div>)}<div className="mt-4 rounded-2xl bg-[#f7faf8] p-4 text-[10px] leading-4 text-slate-500">Production sessions should use secure cookies, refresh-token rotation, expiry, device management, rate limiting and CSRF protection.</div></div> : mfa ? <div className="mt-8 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#e5f3ed] text-[#328171]"><ShieldCheck size={24} /></div><h3 className="mt-4 font-display text-[17px] font-extrabold text-[#27444a]">Verify your identity</h3><p className="mt-2 text-[11px] leading-5 text-slate-400">Enter the 6-digit code from your authenticator app.</p><input aria-label="MFA code" placeholder="000 000" maxLength={7} className="mx-auto mt-5 block h-11 w-32 rounded-xl border border-[#dceae5] bg-[#fbfdfc] text-center font-mono text-[14px] font-bold tracking-[.18em] outline-none focus:border-[#70b7a5]" /><button onClick={() => { onAction("MFA verified · demo sign-in complete"); onClose(); }} className="mt-4 rounded-xl bg-[#173f47] px-5 py-2.5 text-[11px] font-bold text-white">Verify and continue</button><button onClick={() => setMfa(false)} className="mt-3 block mx-auto text-[10px] font-bold text-[#3d8a7a]">Back to sign in</button></div> : <div className="mt-6 space-y-4">{mode === "Email verification" && verified && <div className="rounded-2xl border border-[#b9ded2] bg-[#f2fbf7] p-4 text-[11px] text-[#2b7668]">Verification link sent to the masked address. In production, this step would be delivered by a verified provider.</div>}{mode !== "Email verification" && <><FormField label="Work email" placeholder="name@organization.np" value={mode === "Login" ? "suman.shahi@demo.swasthyaflow.np" : undefined} /></>}{mode === "Login" && <><FormField label="Password" placeholder="Enter your password" /><div className="flex items-center justify-between"><label className="flex items-center gap-2 text-[10px] text-slate-500"><input type="checkbox" className="h-3.5 w-3.5 accent-[#3b9b84]" />Remember this device</label><button onClick={() => setMode("Forgot password")} className="text-[10px] font-bold text-[#3d8a7a]">Forgot password?</button></div></>}{mode === "Reset password" && <><FormField label="New password" placeholder="Use a strong password" /><FormField label="Confirm password" placeholder="Repeat your password" /></>}{mode === "Email verification" && <FormField label="Verification code" placeholder="Enter 6-digit code" />}{mode === "MFA / 2FA" && <><FormField label="Authenticator code" placeholder="000 000" /><div className="rounded-2xl bg-[#f7faf8] p-3 text-[10px] leading-4 text-slate-500">MFA is represented here for the prototype. Production enrollment should support authenticator apps and optional passkeys.</div></>}<button onClick={submit} className="w-full rounded-xl bg-[#173f47] py-3 text-[11px] font-bold text-white">{mode === "Login" ? "Continue to MFA" : mode === "Email verification" ? "Verify email" : mode === "MFA / 2FA" ? "Verify code" : "Continue"}</button></div>}
        <div className="mt-6 border-t border-[#edf2ef] pt-4 text-[9px] leading-4 text-slate-400">Prototype notice: this UI does not implement real authentication, password hashing, account lockout, session security or legal compliance.</div>
      </div>
    </div>
  </div>;
}
function Sidebar({ activePage, setActivePage, open, setOpen, onAction, role }: { activePage: string; setActivePage: (page: string) => void; open: boolean; setOpen: (open: boolean) => void; onAction: ToastFn; role: string }) { const allowed = roleAllowed[role]; const groups = navGroups.map((group) => ({ ...group, items: allowed ? group.items.filter((item) => allowed.includes(item.label)) : group.items })).filter((group) => group.items.length); return <><aside className={cn("fixed inset-y-0 left-0 z-40 w-[260px] -translate-x-full bg-[#102e38] text-white transition-transform duration-300 lg:translate-x-0", open && "translate-x-0")}><div className="flex h-full flex-col"><div className="flex items-center justify-between px-6 pb-5 pt-6"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-[13px] bg-[#e3f4ed] text-[#1c7766]"><HeartPulse size={20} strokeWidth={2.2} /></div><div><p className="font-display text-[15px] font-extrabold tracking-tight">SwasthyaFlow</p><p className="text-[9px] font-bold uppercase tracking-[.2em] text-[#91b8ac]">Nepal healthcare OS</p></div></div><button onClick={() => setOpen(false)} className="rounded-lg p-1 text-white/40 hover:bg-white/10 hover:text-white lg:hidden"><X size={18} /></button></div><div className="mx-5 mb-5 rounded-2xl border border-white/10 bg-white/[.06] p-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#d9efe8] text-[#267a68]"><BriefcaseMedical size={14} /></span><div className="min-w-0 flex-1"><p className="truncate text-[10px] font-bold text-white/90">Himalaya Care Hospital</p><p className="text-[9px] text-white/45">Kathmandu · Bagmati</p></div><ChevronDown size={13} className="text-white/40" /></div></div><nav className="sidebar-scroll flex-1 overflow-y-auto px-3 pb-5">{groups.map((group) => <div key={group.title} className="mb-5"><p className="mb-2 px-3 text-[9px] font-bold uppercase tracking-[.18em] text-white/35">{group.title}</p><div className="space-y-1">{group.items.map(({ label, icon: Icon, badge }) => <button key={label} onClick={() => { setActivePage(label); setOpen(false); }} className={cn("group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[11px] font-medium transition", activePage === label ? "bg-[#e0f3ec] font-bold text-[#205d58] shadow-sm" : "text-white/60 hover:bg-white/[.07] hover:text-white")}><Icon size={16} strokeWidth={activePage === label ? 2.2 : 1.8} /><span className="flex-1">{label}</span>{badge && <span className={cn("rounded-full px-1.5 py-0.5 text-[9px] font-bold", activePage === label ? "bg-[#c3e5d9] text-[#287767]" : "bg-white/10 text-white/60")}>{badge}</span>}</button>)}</div></div>)}</nav><div className="border-t border-white/10 p-4"><button onClick={() => onAction("Help center")} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[11px] text-white/55 hover:bg-white/[.07] hover:text-white"><CircleHelp size={16} /><span className="flex-1">Help center</span><span className="rounded-md border border-white/15 px-1.5 py-0.5 text-[9px]">?</span></button><div className="mt-3 flex items-center gap-3 rounded-2xl bg-white/[.06] p-2.5"><Avatar initials="SS" tone="teal" size="sm" /><div className="min-w-0 flex-1"><p className="truncate text-[11px] font-bold text-white/90">Suman Shahi</p><p className="truncate text-[9px] text-white/45">{role}</p></div><button onClick={() => onAction("Logout confirmation")} className="text-white/35 hover:text-white"><LogOut size={14} /></button></div></div></div></aside>{open && <button aria-label="Close navigation" onClick={() => setOpen(false)} className="fixed inset-0 z-30 bg-[#0d2730]/40 backdrop-blur-sm lg:hidden" />}</>; }

export default function Home({ activePage, setActivePage, role, setRole }: { activePage: string; setActivePage: (page: string) => void; role: string; setRole: (role: string) => void }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [patientQuery, setPatientQuery] = useState("");
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [roleOpen, setRoleOpen] = useState(false);
  const [breakGlass, setBreakGlass] = useState(false);
  const [authOpen, setAuthOpen] = useState(false);

  const notify = (label: string) => {
    if (label === "Break-glass access") { setBreakGlass(true); return; }
    if (label === "Open login screen") { setAuthOpen(true); return; }
    setToast(`${label} · demo action ready`);
    window.setTimeout(() => setToast(""), 2800);
  };
  const navigate = (page: string) => { setActivePage(page); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const changeRole = (next: string) => {
    setRole(next);
    if (roleAllowed[next] && !roleAllowed[next].includes(activePage)) setActivePage("Dashboard");
    setRoleOpen(false);
    notify(`Switched to ${next}`);
  };
  const current = activePage === "Dashboard" ? <Dashboard role={role} onNavigate={navigate} onAction={notify} />
    : activePage === "Patients" ? <PatientsPage onOpenPatient={setSelectedPatient} query={patientQuery} setQuery={setPatientQuery} onAction={notify} />
    : activePage === "Appointments" ? <AppointmentsPage onAction={notify} />
    : activePage === "Doctors & Staff" ? <DoctorsPage onAction={notify} />
    : activePage === "Consultations" ? <ConsultationPage onAction={notify} />
    : activePage === "Prescriptions" ? <PrescriptionPage onAction={notify} />
    : activePage === "Pharmacy" ? <PharmacyPage onAction={notify} />
    : activePage === "Laboratory" ? <LaboratoryPage onAction={notify} />
    : activePage === "Radiology" ? <RadiologyPage onAction={notify} />
    : activePage === "Documents" ? <DocumentsPage onAction={notify} />
    : activePage === "Privacy & Consent" ? <PrivacyPage onAction={notify} />
    : activePage === "Audit Logs" ? <AuditPage onAction={notify} />
    : activePage === "Security Center" ? <SecurityPage onAction={notify} />
    : activePage === "Hospital Management" ? <HospitalPage onAction={notify} />
    : activePage === "Organizations" ? <OrganizationsPage onAction={notify} />
    : activePage === "Reports" ? <ReportsPage onAction={notify} />
    : activePage === "Billing" ? <BillingPage onAction={notify} />
    : activePage === "Insurance" ? <InsurancePage onAction={notify} />
    : activePage === "Interoperability" ? <InteroperabilityPage onAction={notify} />
    : activePage === "Notifications" ? <NotificationsPage onAction={notify} />
    : activePage === "Settings" ? <SettingsPage onAction={notify} />
    : <ModulePage page={activePage} onAction={notify} />;

  return <div className="min-h-screen bg-[#f4f8f6]">
    <Sidebar activePage={activePage} setActivePage={setActivePage} open={sidebarOpen} setOpen={setSidebarOpen} onAction={notify} role={role} />
    <main className="sidebar-open-offset min-h-screen transition-[margin] duration-300">
      <header className="sticky top-0 z-20 border-b border-[#e8efeb]/80 bg-[#f4f8f6]/90 backdrop-blur-xl">
        <div className="flex h-[72px] items-center gap-3 px-4 sm:px-6 lg:px-8">
          <button onClick={() => setSidebarOpen(true)} className="mobile-only grid h-9 w-9 place-items-center rounded-xl border border-[#e1ebe6] bg-white text-slate-600"><Menu size={18} /></button>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="desktop-only grid h-9 w-9 place-items-center rounded-xl border border-transparent text-slate-400 transition hover:border-[#e1ebe6] hover:bg-white hover:text-slate-700">{sidebarOpen ? <PanelLeftClose size={18} /> : <PanelLeftOpen size={18} />}</button>
          <div className="relative ml-1 max-w-sm flex-1 sm:ml-3"><Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={15} /><input aria-label="Global search" value={search} onChange={(e) => setSearch(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && search.trim()) { setPatientQuery(search); navigate("Patients"); } }} placeholder="Search patients, reports, appointments..." className="h-10 w-full rounded-xl border border-[#e2ebe6] bg-white/80 pl-10 pr-3 text-[11px] text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-[#6fb5a4] focus:bg-white focus:ring-4 focus:ring-[#6fb5a4]/10" /><span className="absolute right-2.5 top-1/2 hidden -translate-y-1/2 rounded-md border border-[#e2ebe6] bg-[#f8fbf9] px-1.5 py-0.5 text-[9px] font-medium text-slate-400 sm:block">⌘ K</span></div>
          <div className="ml-auto flex items-center gap-2 sm:gap-3">
            <button onClick={() => notify("Language selector")} className="desktop-only inline-flex items-center gap-1 rounded-xl border border-transparent px-2 py-2 text-[10px] font-bold text-slate-500 hover:border-[#e1ebe6] hover:bg-white"><Languages size={15} />EN</button>
            <div className="relative"><button aria-label="Notifications" onClick={() => setNotificationsOpen(!notificationsOpen)} className="relative grid h-9 w-9 place-items-center rounded-xl border border-transparent text-slate-500 transition hover:border-[#e1ebe6] hover:bg-white"><Bell size={17} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[#df8866] ring-2 ring-[#f4f8f6]" /></button>{notificationsOpen && <div className="absolute right-0 top-12 z-50 w-[300px] rounded-2xl border border-[#e5ede9] bg-white p-4 shadow-2xl"><div className="flex items-center justify-between"><p className="font-display text-[13px] font-extrabold text-[#23434a]">Notifications</p><span className="rounded-full bg-[#fff0d8] px-2 py-1 text-[9px] font-bold text-[#a16d25]">3 new</span></div><div className="mt-3 space-y-2">{["A new appointment was requested", "6 lab results ready for review", "Security review completed"].map((item, i) => <button key={item} onClick={() => { setNotificationsOpen(false); notify(item); }} className="flex w-full gap-2 rounded-xl p-2 text-left hover:bg-[#f8fbf9]"><span className={cn("mt-1 h-2 w-2 shrink-0 rounded-full", i === 1 ? "bg-[#5c87bc]" : i === 2 ? "bg-[#c39b51]" : "bg-[#3b9b84]")} /><span><span className="block text-[11px] font-bold text-[#2d4a50]">{item}</span><span className="mt-0.5 block text-[10px] text-slate-400">No sensitive details shown</span></span></button>)}</div><button onClick={() => { setNotificationsOpen(false); notify("All notifications marked read"); }} className="mt-2 w-full rounded-lg py-2 text-[10px] font-bold text-[#398174] hover:bg-[#f0f8f5]">Mark all as read</button></div>}</div>
            <button onClick={() => notify("Help center")} className="desktop-only grid h-9 w-9 place-items-center rounded-xl border border-transparent text-slate-500 transition hover:border-[#e1ebe6] hover:bg-white"><CircleHelp size={17} /></button>
            <div className="relative"><button onClick={() => setRoleOpen(!roleOpen)} className="flex items-center gap-2 rounded-xl border border-[#e1ebe6] bg-white/70 py-1.5 pl-1.5 pr-2 transition hover:bg-white"><Avatar initials={role === "Patient" ? "AK" : "SS"} tone={role === "Patient" ? "mint" : "teal"} size="sm" /><span className="desktop-only text-left"><span className="block text-[10px] font-bold text-[#29474d]">{role === "Patient" ? "Anisha Koirala" : "Suman Shahi"}</span><span className="block text-[9px] text-slate-400">{role}</span></span><ChevronDown size={13} className="text-slate-400" /></button>{roleOpen && <div className="absolute right-0 top-12 z-50 w-56 rounded-2xl border border-[#e5ede9] bg-white p-2 shadow-2xl"><p className="px-2 pb-2 pt-1 text-[9px] font-bold uppercase tracking-widest text-slate-400">Demo role switcher</p>{roles.map((r) => <button key={r} onClick={() => changeRole(r)} className={cn("flex w-full items-center justify-between rounded-xl px-2.5 py-2 text-left text-[11px] font-semibold transition", role === r ? "bg-[#e5f4ee] text-[#277767]" : "text-slate-600 hover:bg-[#f7faf8]")}>{r}{role === r && <Check size={13} />}</button>)}</div>}</div>
          </div>
        </div>
      </header>
      <div className="container py-7 sm:py-8">{current}<footer className="mt-8 flex flex-col gap-2 border-t border-[#e7efeb] pt-5 text-[10px] text-slate-400 sm:flex-row sm:items-center sm:justify-between"><span>© 2026 SwasthyaFlow Nepal · Frontend prototype</span><span className="flex items-center gap-2"><ShieldCheck size={12} />Mock data only · Not for clinical use</span></footer></div>
    </main>
    {selectedPatient && <PatientModal patient={selectedPatient} onClose={() => setSelectedPatient(null)} onAction={notify} />}
    {breakGlass && <BreakGlassModal onClose={() => setBreakGlass(false)} onAction={notify} />}
    {authOpen && <AuthModal onClose={() => setAuthOpen(false)} onAction={notify} />}
    {toast && <div className="fixed bottom-5 left-1/2 z-[80] -translate-x-1/2 rounded-xl bg-[#173f47] px-4 py-3 text-[11px] font-bold text-white shadow-xl">{toast}</div>}
  </div>;
}
